// Content with portions generated by generative AI platform
package org.eclipse.kura.linux.watchdog;

import java.io.IOException;

import org.eclipse.kura.KuraErrorCode;
import org.eclipse.kura.KuraException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public final class SystemUtils {

    private static final Logger logger = LoggerFactory.getLogger(SystemUtils.class);

    private SystemUtils() {
    }

    public static void rebootSystem() throws KuraException {
        try {
            runCommand("sync");
        } catch (KuraException e) {
            logger.error("Filesystem sync failed. Continuing", e);
        }

        runCommand("reboot");
    }

    public static void runCommand(final String command) throws KuraException {
        try {
            final Process proc = new ProcessBuilder(command.split("\\s+")).start();
            final int exitCode = proc.waitFor();
            if (exitCode != 0) {
                throw new KuraException(KuraErrorCode.OS_COMMAND_ERROR, command, exitCode);
            }
        } catch (IOException e) {
            throw new KuraException(KuraErrorCode.PROCESS_EXECUTION_ERROR, e);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new KuraException(KuraErrorCode.PROCESS_EXECUTION_ERROR, e);
        }
    }
}
